/* Extensions to the existing CityPulse views and Leaflet map. */
'use strict';
let liveMode=true,liveSnapshot=null,liveHistory=[],transitSchedule=null,liveConfig={},refreshing=false,lastFetch=0,roadLayer=null;
const original={overview,forecast,history,sources,models,initMap,areaStyle};
const fmt=(v,o={})=>v?new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',...o}).format(new Date(v)):'—';
const age=v=>{if(!v||!Number.isFinite(Date.parse(v)))return 'Unavailable';let m=Math.max(0,Math.floor((Date.now()-Date.parse(v))/60000));return m<1?'Just now':m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)} hr ago`:`${Math.floor(m/1440)} days ago`};
const num=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-CA');
const signed=v=>v===null||v===undefined?'—':`${v>0?'+':''}${v}%`;
const safeLink=u=>{try{const a=new URL(u);return ['https:','http:'].includes(a.protocol)?esc(a.href):'#'}catch{return '#'}};
const currentArea=()=>liveMode?liveSnapshot?.neighbourhoods.find(n=>n.name===selected):data?.neighbourhoods.find(n=>n.name===selected);
function liveStatus(){const s=liveSnapshot,w=s?.weather,valid=s?.sources.filter(x=>x.status==='healthy').length||0;const service=s?.neighbourhoods.some(n=>n.departures!==null)?s.neighbourhoods.reduce((v,n)=>v+(n.departures||0),0):null;return `<div class="status-region"><div class="status-heading"><strong>Metro Vancouver</strong><span>${fmt(new Date(),{weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'})} PT</span><span class="dataset-badge ${valid<3?'delayed':''}">${valid===3?'LIVE SOURCES':valid?'PARTIAL DATA':'CONNECTING'}</span><span class="status-freshness">Checked <span data-age="${s?.collected_at||''}">${age(s?.collected_at)}</span></span><button class="text-button" id="refresh-live">↻ Refresh</button></div><div class="status-metrics"><span>Road closures <b>${num(s?.totals.closures)}</b></span><span>Construction <b>${num(s?.totals.construction)}</b></span><span>Scheduled stops / hr <b>${num(service)}</b></span><span><b>${w?num(w.temperature)+'°C':'—'}</b> ${esc(w?.label||'Weather unavailable')}</span></div></div>`}
function liveExceptions(){const rows=[...(liveSnapshot?.neighbourhoods||[])].sort((a,b)=>(b.closures??-1)-(a.closures??-1)).slice(0,4);return `<aside class="card exception-panel"><div class="card-head"><h2>Current conditions</h2></div><dl class="summary-rows"><div><dt>Reported closures</dt><dd>${num(liveSnapshot?.totals.closures)}</dd></div><div><dt>Neighbourhoods affected</dt><dd>${liveSnapshot?liveSnapshot.neighbourhoods.filter(n=>n.closures>0).length:'—'}</dd></div><div><dt>Historical comparison</dt><dd class="small-value">Baseline building</dd></div></dl><div class="section-label">MOST REPORTED CLOSURES</div><div class="anomaly-list">${rows.map(n=>`<button class="anomaly-row ${selected===n.name?'selected':''}" data-detail="${esc(n.name)}"><div class="anomaly-top">${esc(n.name)}<span class="change">${num(n.closures)}</span></div><p>${num(n.construction)} construction projects</p></button>`).join('')}</div><div class="source-footnote">Municipal reports, not measured traffic volume. <a href="#sources">Source freshness →</a></div></aside>`}
overview=function(){if(!liveMode)return original.overview().replace(/<section id="analysis-area"[\s\S]*$/,`<section id="analysis-area" class="analysis-area">${analysisContent()}</section>`);return `${liveStatus()}<div class="operations-grid"><article class="card map-card"><div class="card-head"><div><h2>Vancouver · reported road impacts</h2><p>22 city neighbourhoods</p></div><select id="map-layer" class="select" aria-label="Map data layer"><option value="closures">Road closures</option><option value="construction">Construction</option><option value="service">Scheduled transit</option></select></div><div class="map-wrap"><div id="map" class="map" aria-label="Interactive Vancouver neighbourhood map"></div><div class="map-key" id="live-map-key"><span><i></i>0 reports</span><span><i class="busy"></i>1–2</span><span><i class="high"></i>3+</span></div></div><div class="map-bottom"><span>Select a neighbourhood to inspect</span><a href="#neighbourhoods">All neighbourhoods →</a></div></article>${liveExceptions()}</div><section id="analysis-area" class="analysis-area">${analysisContent()}</section>`};
function simpleChart(values,labels,unit){const w=700,h=190,p=32,max=Math.max(1,...values)*1.15,pts=values.map((v,i)=>`${p+i*(w-p-10)/Math.max(1,values.length-1)},${h-30-v/max*(h-55)}`);return `<div class="chart live-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(unit)} over ${values.length} hours">${[0,.5,1].map(f=>`<line class="grid" x1="${p}" x2="${w}" y1="${h-30-f*(h-55)}" y2="${h-30-f*(h-55)}"/><text x="1" y="${h-26-f*(h-55)}">${Math.round(f*max)}</text>`).join('')}<polyline class="line" points="${pts.join(' ')}"/>${values.map((v,i)=>`<circle cx="${pts[i].split(',')[0]}" cy="${pts[i].split(',')[1]}" r="3" fill="#335f49"><title>${esc(labels[i])}: ${v} ${esc(unit)}</title></circle>${i%Math.max(1,Math.floor(values.length/6))===0?`<text x="${pts[i].split(',')[0]}" y="${h-6}">${esc(labels[i])}</text>`:''}`).join('')}</svg></div>`}
function analysisContent(){const n=currentArea();if(!n)return '<article class="card full-panel"><h2>Select a neighbourhood</h2></article>';let body,metrics,next;
if(liveMode){metrics=[['Road closures',n.closures],['Construction',n.construction],['Scheduled stops / hr',n.departures]];body=`<h3>Reported road impacts</h3>${n.projects.length?`<div class="project-list">${n.projects.slice(0,8).map(p=>`<div class="project-row"><span class="report-type ${p.type}">${p.type==='closure'?'CLOSURE':'WORKS'}</span><div><a href="${safeLink(p.url)}" target="_blank" rel="noreferrer">${esc(p.title)} ↗</a><small>${p.completion?'Expected completion '+esc(p.completion):'Completion date not provided'}</small></div></div>`).join('')}</div>`:'<p class="muted">No reports mapped in the available sources. This does not rule out unreported disruptions.</p>'}<h3>Reported closures · recent history</h3>${n.history.length>=2?simpleChart(n.history.map(h=>h.value),n.history.map(h=>fmt(h.timestamp,{hour:'2-digit',hourCycle:'h23'})),'closures'):'<div class="empty-analysis">History collection has started. The chart appears after another hourly observation.</div>'}<p class="analysis-note">${n.range?`Typical same-weekday/hour range: ${n.range.join('–')} closures.`:'A same-weekday/hour reference needs at least four distinct historical dates.'}</p>`;next=n.service.length?n.service.slice(0,6).map(h=>[fmt(h.timestamp,{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}),h.departures]):[['Schedule unavailable',null]];
}else{metrics=[['Activity',n.activity],['Typical Friday evening',n.typical],['Change',signed(n.change)]];const high=n.activity>(n.typical_range?.[1]??100);body=`${n.typical_range?`<div class="range-plot" role="img" aria-label="Actual ${n.activity}; typical range ${n.typical_range.join(' to ')}"><span class="actual-dot" style="left:${Math.min(96,n.activity)}%"><b>${n.activity}</b>●</span><div class="range-axis"><i style="left:${n.typical_range[0]}%;width:${n.typical_range[1]-n.typical_range[0]}%"></i></div><span class="range-caption">Typical range ${n.typical_range.join('–')}</span></div>`:''}<span class="condition-label ${high?'elevated':''}">${high?'Unusually high':n.activity<(n.typical_range?.[0]??0)?'Below typical range':'Within typical range'}</span><h3>Associated factors</h3><div class="factor-list">${n.drivers.slice(0,3).map(d=>`<div><span>${esc(d.label)}</span><span>${Math.abs(d.value)>=10?'High':Math.abs(d.value)>=4?'Moderate':'Low'} influence</span></div>`).join('')}</div><p class="analysis-note">Sample-model associations, not proven causes.</p><h3>Activity · last 24 hours</h3><div class="chart wide-chart">${chart(n.hourly||data.hourly,n.hourly_reference||data.rhythm_baseline,true,['19:00','01:00','07:00','13:00','18:00'])}</div><div class="legend"><span><i></i>Actual</span><span><i class="dashed"></i>Typical weekday</span></div>`;next=[18,19,20,21,22].map(h=>[h+':00',n.forecast[h]]);}
return `<article class="card neighbourhood-detail"><div class="card-head"><div><div class="detail-eyebrow">SELECTED NEIGHBOURHOOD${liveMode?'':' · DEMO'}</div><h2>${esc(n.name)}</h2></div><button class="text-button" data-analysis="${esc(n.name)}">View analysis details ↗</button></div><div class="detail-summary">${metrics.map(([k,v])=>`<div><span>${k}</span><strong>${typeof v==='string'?v:num(v)}</strong></div>`).join('')}</div><div class="detail-body">${body}</div></article><article class="card forecast-aside"><div class="card-head"><h2>${liveMode?'Scheduled service · next hours':'Tomorrow evening'}</h2></div><dl class="summary-rows">${next.map(([k,v])=>`<div><dt>${k}</dt><dd>${num(v)}</dd></div>`).join('')}</dl><div class="source-footnote">${liveMode?'Scheduled stop departures, not arrivals or passenger demand.':'Expected sample activity. A validated likely range is not available.'}</div><a class="card-link" href="#forecast">Hourly outlook →</a></article>`}
detail=function(name){if(!(liveMode?liveSnapshot?.neighbourhoods:data?.neighbourhoods)?.some(n=>n.name===name))return;selected=name;if(view!=='overview'){location.hash='overview';return}$('#analysis-area').innerHTML=analysisContent();if(areas)areas.setStyle(f=>areaStyle(f));$('#analysis-area').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})};
function analysisDialog(name,demo=false){const n=demo?data.neighbourhoods.find(n=>n.name===name):(liveMode?liveSnapshot?.neighbourhoods:data.neighbourhoods).find(n=>n.name===name);if(!n)return;const useLive=liveMode&&!demo;let rows=useLive?[['Observed measure','Municipal road-closure reports'],['Current count',num(n.closures)],['Activity model','Not deployed on live observations'],['Historical reference',n.range?n.range.join('–'):'Insufficient history'],['Transit','GTFS scheduled stop departures'],['Geospatial method','Report centroid within official neighbourhood polygon'],['Records outside mapped neighbourhoods',liveSnapshot.unmapped]]:[['Forecast model',data.metrics.model+' · '+(data.metrics.model_version||'v1')],['Observed activity / baseline',n.activity+' / '+num(n.typical)],['Typical 10th–90th percentile',n.typical_range?.join('–')||'Unavailable'],['Anomaly detector','Isolation Forest'],['Scaled anomaly score',n.anomaly_score.toFixed(3)],['Last trained',fmt(data.metrics.trained_at||data.generated_at,{dateStyle:'medium',timeStyle:'short'})],['One-step MAE / baseline MAE',data.metrics.mae+' / '+data.metrics.baseline_mae]];$('#detail-content').innerHTML=`<div class="detail-eyebrow">ANALYSIS DETAILS · ${useLive?'LIVE SOURCES':'SYNTHETIC DATA'}</div><h2>${esc(n.name)}</h2><dl class="technical-rows">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${useLive?'':`<h3>Feature contributions</h3><div class="drivers">${n.drivers.map(d=>`<div class="driver"><span>${esc(d.label)}</span><div class="driver-track"><i class="${d.value<0?'negative':''}" style="width:${Math.min(100,Math.abs(d.value)*3)}%"></i></div><b>${d.value>0?'+':''}${d.value}</b></div>`).join('')}</div>`}<p class="muted">${useLive?'The live map reports source observations. It does not estimate crowd size or use the synthetic model to score real neighbourhoods.':'Exact additive Ridge contributions on the current conditional estimate, before clipping. These are not SHAP values or causal effects. The empirical reference range is not a forecast confidence interval.'}</p>`;$('#detail').showModal()}
function evidenceTable(rows){return `<div class="table-wrap"><table><thead><tr>${(liveMode?['Neighbourhood','Closures','Construction','Scheduled stops / hr','Historical comparison']:['Neighbourhood','Activity','Typical','Change','Current condition']).map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(n=>`<tr data-id="${esc(n.name)}" tabindex="0" aria-label="Explore ${esc(n.name)}"><td><b>${esc(n.name)}</b></td>${(liveMode?[num(n.closures),num(n.construction),num(n.departures),n.range?(n.unusual?'Above typical range':'Within range'):'Baseline building']:[n.activity,num(n.typical),signed(n.change),n.activity>(n.typical_range?.[1]??100)?'Unusually high':n.activity<(n.typical_range?.[0]??0)?'Below typical range':'Within range']).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
neighbourhoods=function(){const rows=[...(liveMode?liveSnapshot?.neighbourhoods||[]:data.neighbourhoods)].sort((a,b)=>liveMode?(b.closures??-1)-(a.closures??-1):b.activity-a.activity);return `<article class="card full-panel"><div class="toolbar"><input class="input" id="search" type="search" placeholder="Search neighbourhoods…" aria-label="Search neighbourhoods"><select id="sort" class="select" aria-label="Sort neighbourhoods"><option value="${liveMode?'closures':'activity'}">${liveMode?'Most closures':'Highest activity'}</option><option value="name">Name A–Z</option></select></div><div id="neighbourhood-table">${evidenceTable(rows)}</div></article>`};
forecast=function(){return `<article class="card full-panel"><div class="toolbar"><div><h2>${liveMode?'Weather & scheduled service':'Tomorrow’s activity · model demo'}</h2><p class="muted">${liveMode?'Next 24 hours · Vancouver time':'Saturday, September 12 · synthetic data'}</p></div><select id="forecast-area" class="select" aria-label="Forecast neighbourhood">${(liveMode?liveSnapshot?.neighbourhoods||[]:data.neighbourhoods).map(n=>`<option ${n.name===selected?'selected':''}>${esc(n.name)}</option>`).join('')}</select></div><div id="forecast-body">${forecastBody(selected)}</div></article>`};
forecastBody=function(name=selected){const n=liveMode?liveSnapshot?.neighbourhoods.find(n=>n.name===name):data.neighbourhoods.find(n=>n.name===name);if(!n)return '<p class="muted">No forecast data available.</p>';if(!liveMode)return `<div class="chart wide-chart">${chart(n.forecast,data.baseline,true)}</div><div class="legend"><span><i></i>Expected activity</span><span><i class="dashed"></i>Historical city reference</span></div><div class="forecast-hours">${[18,19,20,21,22].map(h=>`<div><span>${h}:00</span><strong>${n.forecast[h]}</strong></div>`).join('')}</div><p class="analysis-note">Sample forecasts use typical future weather, event and transit inputs. A validated likely range is not available.</p><button class="button" data-analysis="${esc(n.name)}">View analysis details</button>`;const w=liveSnapshot.weather;return `<p class="analysis-note">Forecast weather and scheduled service are shown directly. Live activity predictions are not yet validated.</p>${w?.forecast.length?simpleChart(w.forecast.map(h=>h.temperature),w.forecast.map(h=>fmt(h.timestamp,{hour:'2-digit',hourCycle:'h23'})),'°C'):''}<div class="table-wrap"><table><thead><tr><th>Time</th><th>Temperature</th><th>Chance of rain</th><th>Scheduled stop departures</th></tr></thead><tbody>${(w?.forecast||n.service||[]).map(h=>{const service=n.service.find(t=>Date.parse(t.timestamp)===Date.parse(h.timestamp));return `<tr><td>${fmt(h.timestamp,{weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'})}</td><td>${num(h.temperature)}${h.temperature!==undefined?'°C':''}</td><td>${num(h.rain_probability)}${h.rain_probability!==undefined?'%':''}</td><td>${num(service?.departures)}</td></tr>`}).join('')}</tbody></table></div><p class="analysis-note">Transit counts represent scheduled calls at mapped stops, not unique trips, actual arrivals or passenger counts.</p>`};
anomalyPage=function(){if(liveMode){const rows=(liveSnapshot?.neighbourhoods||[]).filter(n=>n.unusual);return `<article class="card full-panel"><h2>Active anomalies</h2><p>${rows.length?rows.length+' neighbourhoods exceed the historical range for road-closure reports.':'No supported unusual-activity claims yet. A weekday/hour reference needs four distinct historical dates.'}</p>${rows.length?evidenceTable(rows):`<div class="empty-analysis">Collecting live history · ${num(liveSnapshot?.history_hours)} hourly observations</div>`}<h3>Current road impacts</h3>${evidenceTable([...(liveSnapshot?.neighbourhoods||[])].filter(n=>n.closures>0).sort((a,b)=>b.closures-a.closures))}</article>`}return `<article class="card full-panel"><div class="toolbar"><div><h2>Largest activity deviations</h2><p class="muted">Synthetic observations · Friday evening</p></div><select id="severity" class="select" aria-label="Filter anomaly severity"><option value="all">All deviations</option><option value="high">Above typical range</option></select></div><div id="anomaly-table">${evidenceTable(anomalies(30))}</div></article>`};
history=function(){if(!liveMode)return original.history();return `<article class="card full-panel"><h2>Live observation history</h2><p>Hourly road-closure counts retained by the scheduled collector. Source extracts update daily, so repeated counts are expected.</p>${liveHistory.length>=2?simpleChart(liveHistory.slice(-48).map(h=>Object.values(h.neighbourhoods).reduce((a,b)=>a+b,0)),liveHistory.slice(-48).map(h=>fmt(h.timestamp,{hour:'2-digit',hourCycle:'h23'})),'reported closures'):'<div class="empty-analysis">History collection has started. No synthetic comparisons are added to this view.</div>'}<div class="table-wrap"><table><thead><tr><th>Collected hour</th><th>Source updated</th><th>Mapped closures</th></tr></thead><tbody>${liveHistory.slice(-24).reverse().map(h=>`<tr><td>${fmt(h.timestamp,{dateStyle:'medium',timeStyle:'short'})}</td><td>${fmt(h.observed_at,{dateStyle:'medium',timeStyle:'short'})}</td><td>${Object.values(h.neighbourhoods).reduce((a,b)=>a+b,0)}</td></tr>`).join('')}</tbody></table></div></article>`};
sources=function(){const valid=transitSchedule&&Date.parse(transitSchedule.valid_until)>Date.now();const rows=[...(liveSnapshot?.sources||[]),{name:'TransLink GTFS',status:valid?'healthy':transitSchedule?'stale':'unavailable',checked_at:transitSchedule?.fetched_at,updated_at:transitSchedule?.updated_at,records:transitSchedule?.records,cadence:'Weekly source · daily collection',url:'https://www.translink.ca/about-us/doing-business-with-translink/app-developer-resources/gtfs/gtfs-data'},{name:'Vancouver boundaries',status:'static',records:22,cadence:'Static official geography',url:'https://opendata.vancouver.ca/explore/dataset/local-area-boundary/'},{name:'Events / live transit positions',status:'not connected',records:null,cadence:'Not used in live analysis'}];return `<article class="card full-panel"><h2>Data sources</h2><p>Automatic source checks every five minutes while the page is open. Upstream publication times are shown separately.</p><div class="table-wrap"><table><thead><tr><th>Source</th><th>Status</th><th>Source updated</th><th>Last checked</th><th>Records</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.url?`<a href="${safeLink(r.url)}" target="_blank" rel="noreferrer"><b>${esc(r.name)}</b> ↗</a>`:esc(r.name)}<small class="cell-note">${esc(r.cadence||'')}</small></td><td><span class="health ${esc(r.status)}">${r.status==='healthy'?'Available':esc(r.status)}</span></td><td>${r.updated_at?fmt(r.updated_at,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):r.status==='static'?'Static geometry':'Not provided'}</td><td>${r.checked_at?age(r.checked_at):'—'}</td><td>${num(r.records)}</td></tr>`).join('')}</tbody></table></div><div class="source-disclosures"><p>Road reports are a daily municipal extract. Open-Meteo conditions are model estimates, not a street-level weather sensor. TransLink data is scheduled service, not real-time operations.</p><p>Continuous collection uses GitHub Actions when enabled. Scheduled runs can be delayed; timestamps reflect the actual successful run.</p>${transitSchedule?`<p>${esc(transitSchedule.attribution)}</p>`:''}<p>City of Vancouver data: Open Government Licence – Vancouver. OpenStreetMap contributors are credited on the map.</p></div></article>`};
models=function(){const m=data.metrics;return `<article class="card full-panel"><h2>Model performance</h2><p><b>Live production activity model: not deployed.</b> The live surface displays source observations. The experiment below was trained and evaluated on synthetic data.</p><div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Version</th><th>MAE</th><th>RMSE</th><th>Role</th></tr></thead><tbody><tr><td>Historical weekday/hour mean</td><td>baseline-v1</td><td>${m.baseline_mae}</td><td>Not recorded</td><td>Best measured reference</td></tr><tr><td>${esc(m.model)}</td><td>${esc(m.model_version||'ridge-demo-v1')}</td><td>${m.mae}</td><td>${m.rmse}</td><td>Demo estimate</td></tr></tbody></table></div><dl class="technical-rows">${[['Training window',(m.train_start||'Not recorded')+' – '+m.train_end],['Training / holdout rows',num(m.train_rows)+' / '+num(m.test_rows)],['Last trained',fmt(m.trained_at||data.generated_at,{dateStyle:'medium',timeStyle:'short'})],['Validation','Last seven days by timestamp; preprocessing fitted on training only.'],['Forecast horizon evaluated','One-step conditional; recursive 24-hour forecasts not separately backtested.'],['Anomaly detector / city states','Isolation Forest / five-cluster K-Means'],['Explainability','Exact additive Ridge contributions; SHAP not used.']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><h3>Local feature contributions · Downtown sample</h3><button class="button" data-analysis="Downtown" data-demo-analysis="true">Inspect feature contributions</button><p class="analysis-note">Two measured experiments are shown. Additional versions, production accuracy and confidence intervals are not fabricated.</p></article>`};
